//! 🎟️ Original retained-work authority reaches physical paged reservations and committed retained payload writes.
use semio_framework_value_control_contract::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use semio_framework_value_paged_list::list::PagedList;
#[derive(Clone,Copy,Default)]
struct Hold{owner:usize,length:usize,bytes:usize,active:bool}
pub struct RetainedWorkLedger{grant:RetainedCloneGrant,actual:RetainedCloneProgress,pending:Option<RetirementDemand>,holds:[Hold;64],held:usize,nesting:usize,semantic_items:usize,actual_work:u128}
impl RetainedWorkLedger{
 pub fn new(grant:RetainedCloneGrant)->Self{Self{grant,actual:Default::default(),pending:None,holds:[Hold::default();64],held:0,nesting:0,semantic_items:0,actual_work:0}}
 /// ⏱️ Borrows cumulative actual storage work, including failed allocator attempts.
 pub fn actual_work(&self)->u128{self.actual_work}
 pub fn blocked(&self)->bool{self.pending.is_some()}
 pub fn enter(&mut self)->Option<bool>{let depth=self.nesting+1;if self.remaining().maximum_items==0||self.grant.maximum_depth<depth{self.pending=Some(RetirementDemand{depth,..Default::default()});return None;}let root=self.nesting==0;self.nesting+=1;Some(root)}
 pub fn exit(&mut self){self.nesting-=1;}
 pub fn can_step(&mut self)->bool{let depth=self.nesting.max(1);if self.remaining().maximum_items==0||self.grant.maximum_depth<depth{self.pending=Some(RetirementDemand{depth,..Default::default()});return false;}if self.nesting==0{self.note_source(true);}true}
 pub fn note_source(&mut self,root:bool){if root{self.semantic_items+=1;self.actual.copied_items=self.actual.copied_items.max(self.semantic_items);}}
 pub fn copy_bytes(&mut self,bytes:usize)->bool{let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_copy_bytes<bytes||remaining.maximum_depth<self.nesting+1{self.pending=Some(RetirementDemand{copy_bytes:self.held+bytes,depth:self.nesting+1,..Default::default()});return false;}self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=bytes;true}
 pub fn child_grant(&self)->RetainedCloneGrant{let grant=self.remaining();RetainedCloneGrant{maximum_depth:grant.maximum_depth.saturating_sub(self.nesting),..grant}}
 pub fn consume_child(&mut self,used:RetainedCloneProgress)->Result<(),&'static str>{let remaining=self.child_grant();self.actual.copied_items=self.actual.copied_items.max(used.copied_items);self.actual.copied_bytes=self.actual.copied_bytes.checked_add(used.copied_bytes).ok_or("retained work child copy overflow")?;self.actual.retained_capacity_bytes=self.actual.retained_capacity_bytes.checked_add(used.retained_capacity_bytes).ok_or("retained work child capacity overflow")?;self.actual.released_bytes=self.actual.released_bytes.checked_add(used.released_bytes).ok_or("retained work child release overflow")?;if used.copied_items>remaining.maximum_items||used.copied_bytes>remaining.maximum_copy_bytes||used.retained_capacity_bytes>remaining.maximum_capacity_bytes||used.released_bytes>remaining.maximum_release_bytes{return Err("retained work child exceeded original authority");}Ok(())}
 pub fn admits_absolute(&self,demand:RetirementDemand)->bool{let remaining=self.remaining();remaining.maximum_items>0&&self.grant.maximum_copy_bytes.saturating_sub(self.actual.copied_bytes)>=demand.copy_bytes&&remaining.maximum_capacity_bytes>=demand.capacity_bytes&&remaining.maximum_release_bytes>=demand.release_bytes&&self.grant.maximum_depth>=demand.depth}
 pub fn require_absolute(&mut self,demand:RetirementDemand){self.pending=Some(demand);}
 pub fn require_child(&mut self,demand:RetirementDemand)->Result<(),&'static str>{self.pending=Some(RetirementDemand{copy_bytes:demand.copy_bytes.checked_add(self.held).ok_or("retained work child demand overflow")?,depth:demand.depth.checked_add(self.nesting).ok_or("retained work child depth overflow")?,..demand});Ok(())}
 pub fn receipt(&self)->RetainedCloneProgress{self.actual}
 pub fn remaining(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.grant.maximum_items.saturating_sub(self.semantic_items),maximum_copy_bytes:self.grant.maximum_copy_bytes.saturating_sub(self.actual.copied_bytes).saturating_sub(self.held),maximum_capacity_bytes:self.grant.maximum_capacity_bytes.saturating_sub(self.actual.retained_capacity_bytes),maximum_release_bytes:self.grant.maximum_release_bytes.saturating_sub(self.actual.released_bytes),maximum_depth:self.grant.maximum_depth}}
 pub fn next_demand(&self)->RetirementDemand{self.pending.unwrap_or(RetirementDemand{depth:1,..Default::default()})}
 pub fn slot_demand<T>(values:&PagedList<T,{usize::MAX}>)->Result<RetirementDemand,&'static str>{if values.has_reserved_slot(){return Ok(RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()});}Ok(RetirementDemand{copy_bytes:values.next_reserve_copy_byte_demand().map_err(|_|"retained work slot copy demand")?,capacity_bytes:values.next_allocation_bytes().map_err(|_|"retained work slot capacity demand")?,depth:values.next_reserve_depth_demand().map_err(|_|"retained work slot depth demand")?,release_bytes:0})}

 pub fn slot<T>(&mut self,values:&mut PagedList<T,{usize::MAX}>,effect:&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->Result<bool,semio_framework_value_control_contract::ValueError>{
  use semio_framework_value_control_contract::ValueError;use semio_framework_value_paged_list::{PagedListReservationOutcome,PagedListReservationFailure};
  let owner=values as*const PagedList<T,{usize::MAX}>as usize;let length=values.len();if self.holds.iter().any(|hold|hold.active&&hold.owner==owner&&hold.length==length){return Ok(true)}
  let mut demand=Self::slot_demand(values).map_err(ValueError::invariant)?;demand.depth=demand.depth.checked_add(self.nesting).ok_or_else(||ValueError::invariant("retained work slot nesting overflow"))?;let remaining=self.remaining();
  if remaining.maximum_items==0||remaining.maximum_copy_bytes<demand.copy_bytes||remaining.maximum_capacity_bytes<demand.capacity_bytes||remaining.maximum_depth<demand.depth{self.pending=Some(RetirementDemand{copy_bytes:demand.copy_bytes.checked_add(self.held).ok_or_else(||ValueError::invariant("retained work held slot extent overflow"))?,..demand});return Ok(false)}
  if demand.capacity_bytes>0{
   let maximum=effect.remaining_work_units()?;let grant=self.child_grant();let turn=values.reserve_one(&mut effect.reborrow(grant,maximum)?);self.actual_work=self.actual_work.checked_add(turn.work).ok_or_else(||ValueError::invariant("retained work aggregate overflow"))?;
   let progress=match turn.result{
    Ok(PagedListReservationOutcome::Denied)=>{self.pending=Some(demand);return Ok(false)},
    Ok(PagedListReservationOutcome::Ready(progress))=>RetainedCloneProgress{copied_items:usize::from(progress.progressed),copied_bytes:progress.placed_bytes,retained_capacity_bytes:progress.allocated_bytes,..Default::default()},
    Err(PagedListReservationFailure::Work(error))=>return Err(error),
    Err(PagedListReservationFailure::Allocation{error,copied_bytes})=>{let progress=RetainedCloneProgress{copied_items:usize::from(copied_bytes!=0||error.allocated_bytes!=0),copied_bytes,retained_capacity_bytes:error.allocated_bytes,..Default::default()};self.consume_child(progress).map_err(ValueError::invariant)?;return Err(ValueError::from(error.refusal()).with_retained_progress(progress))}
   };
   self.consume_child(progress).map_err(ValueError::invariant)?;let mut next=Self::slot_demand(values).map_err(ValueError::invariant)?;next.copy_bytes=next.copy_bytes.checked_add(self.held).ok_or_else(||ValueError::invariant("retained work held slot extent overflow"))?;next.depth=next.depth.checked_add(self.nesting).ok_or_else(||ValueError::invariant("retained work slot nesting overflow"))?;self.pending=Some(next);return Ok(false)
  }
  let hold=self.holds.iter_mut().find(|hold|!hold.active).ok_or_else(||ValueError::invariant("retained work hold count"))?;*hold=Hold{owner,length,bytes:size_of::<T>(),active:true};self.held=self.held.checked_add(hold.bytes).ok_or_else(||ValueError::invariant("retained work held slot extent overflow"))?;Ok(true)
 }
 pub fn contiguous<T>(&mut self,values:&mut Vec<T>,target:usize,actual:&mut Option<usize>)->Result<bool,&'static str>{if values.capacity()>=target{return Ok(true);}if values.capacity()!=0||!values.is_empty(){return Err("retained work contiguous owner replacement refused");}let bytes=target.checked_mul(size_of::<T>()).ok_or("retained work contiguous capacity overflow")?;let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_capacity_bytes<bytes||remaining.maximum_depth<self.nesting+1{self.pending=Some(RetirementDemand{copy_bytes:self.held,capacity_bytes:bytes,release_bytes:0,depth:self.nesting+1});return Ok(false);}std::alloc::Layout::array::<T>(target).map_err(|_|"retained work contiguous layout overflow")?;if actual.is_some(){return Err("retained work actual allocation marker occupied")}if bytes!=0{*actual=Some(0)}self.actual_work+=1;values.try_reserve_exact(target).map_err(|_|"retained work contiguous admission failed")?;let observed=values.capacity()*size_of::<T>();*actual=if bytes==0{None}else{Some(observed)};let actual=observed;self.actual.retained_capacity_bytes+=actual;self.actual.copied_items=self.actual.copied_items.max(1);self.pending=Some(RetirementDemand{copy_bytes:self.held+size_of::<T>(),depth:self.nesting+1,..Default::default()});if actual>remaining.maximum_capacity_bytes{return Err("retained work contiguous allocation exceeded original authority");}Ok(false)}
 pub fn reserve_vec<T>(&mut self,values:&mut Vec<T>,target:usize,actual:&mut Option<usize>)->Result<bool,&'static str>{
  if values.capacity()>=target{return Ok(true);}
  let width=size_of::<T>();let capacity=target.checked_mul(width).ok_or("retained work vector capacity overflow")?;let release=values.capacity().checked_mul(width).ok_or("retained work vector release overflow")?;let copy=values.len().checked_mul(width).ok_or("retained work vector copy overflow")?;let remaining=self.remaining();let demand=RetirementDemand{copy_bytes:self.held.checked_add(copy).ok_or("retained work vector held copy overflow")?,capacity_bytes:capacity,release_bytes:release,depth:self.nesting+1};
  if remaining.maximum_items==0||remaining.maximum_copy_bytes<copy||remaining.maximum_capacity_bytes<capacity||remaining.maximum_release_bytes<release||remaining.maximum_depth<demand.depth{self.pending=Some(demand);return Ok(false);}
  std::alloc::Layout::array::<T>(target).map_err(|_|"retained work vector layout overflow")?;if actual.is_some(){return Err("retained work actual allocation marker occupied")}if capacity!=0{*actual=Some(0)}self.actual_work+=1;values.try_reserve_exact(target-values.len()).map_err(|_|"retained work vector admission failed")?;let observed=values.capacity().checked_mul(width).ok_or("retained work vector actual capacity overflow")?;*actual=if capacity==0{None}else{Some(observed)};let actual=observed;self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=copy;self.actual.retained_capacity_bytes+=actual;self.actual.released_bytes+=release;self.pending=Some(RetirementDemand{copy_bytes:self.held+width,depth:self.nesting+1,..Default::default()});if actual>remaining.maximum_capacity_bytes{return Err("retained work vector allocation exceeded original authority");}Ok(false)
 }
 pub fn reserve_string(&mut self,value:&mut String,target:usize,actual:&mut Option<usize>)->Result<bool,&'static str>{
  if value.capacity()>=target{return Ok(true);}let copy=value.len();let release=value.capacity();let remaining=self.remaining();let demand=RetirementDemand{copy_bytes:self.held.checked_add(copy).ok_or("retained work string held copy overflow")?,capacity_bytes:target,release_bytes:release,depth:self.nesting+1};
  if remaining.maximum_items==0||remaining.maximum_copy_bytes<copy||remaining.maximum_capacity_bytes<target||remaining.maximum_release_bytes<release||remaining.maximum_depth<demand.depth{self.pending=Some(demand);return Ok(false);}
  std::alloc::Layout::array::<u8>(target).map_err(|_|"retained work string layout overflow")?;if actual.is_some(){return Err("retained work actual allocation marker occupied")}if target!=0{*actual=Some(0)}self.actual_work+=1;value.try_reserve_exact(target-value.len()).map_err(|_|"retained work string admission failed")?;let observed=value.capacity();*actual=if target==0{None}else{Some(observed)};let actual=observed;self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=copy;self.actual.retained_capacity_bytes+=actual;self.actual.released_bytes+=release;self.pending=Some(RetirementDemand{copy_bytes:self.held,depth:self.nesting+1,..Default::default()});if actual>remaining.maximum_capacity_bytes{return Err("retained work string allocation exceeded original authority");}Ok(false)
 }
 pub fn string_push(&mut self,value:&mut String,source:&str)->Result<bool,&'static str>{let target=value.len().checked_add(source.len()).ok_or("retained work string length overflow")?;if value.capacity()<target{return Err("retained work string slot was not admitted");}if !self.copy_bytes(source.len()){return Ok(false);}self.actual_work+=1;value.push_str(source);Ok(true)}
 pub fn arc_ready<T>(&mut self)->Result<bool,&'static str>{let mut demand=semio_framework_value_retirement::retirement::arc_custody::shared_allocation_value_demand::<T>().map_err(|_|"retained work shared allocation demand overflow")?;demand.depth=demand.depth.checked_add(self.nesting).ok_or("retained work shared depth overflow")?;let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_copy_bytes<demand.copy_bytes||remaining.maximum_capacity_bytes<demand.capacity_bytes||remaining.maximum_depth<demand.depth{self.pending=Some(RetirementDemand{copy_bytes:self.held.checked_add(demand.copy_bytes).ok_or("retained work shared held copy overflow")?,..demand});return Ok(false);}Ok(true)}
 pub fn arc_new<T>(&mut self,value:T,actual:&mut Option<usize>)->Result<std::sync::Arc<T>,(&'static str,T)>{match self.arc_ready::<T>(){Ok(true)=>{},Ok(false)=>return Err(("retained work shared birth authority missing",value)),Err(error)=>return Err((error,value))}let turn=semio_framework_value_retirement::retirement::arc_custody::admit_shared_allocation(value,self.child_grant(),actual);self.actual_work=self.actual_work.saturating_add(turn.work);let(value,progress)=turn.result.map_err(|(_,value)|("retained work shared allocation failed",value))?;self.actual.copied_items=self.actual.copied_items.max(progress.copied_items);self.actual.copied_bytes+=progress.copied_bytes;self.actual.retained_capacity_bytes+=progress.retained_capacity_bytes;Ok(value)}
 pub fn vec_slot<T>(&mut self,values:&mut Vec<T>)->Result<bool,&'static str>{if values.len()==values.capacity(){return Err("retained work contiguous slot was not admitted");}let owner=values as*const Vec<T>as usize;let length=values.len();if self.holds.iter().any(|hold|hold.active&&hold.owner==owner&&hold.length==length){return Ok(true);}let bytes=size_of::<T>();let remaining=self.remaining();if remaining.maximum_items==0||remaining.maximum_copy_bytes<bytes||remaining.maximum_depth<self.nesting+1{self.pending=Some(RetirementDemand{copy_bytes:self.held+bytes,depth:self.nesting+1,..Default::default()});return Ok(false);}let hold=self.holds.iter_mut().find(|hold|!hold.active).ok_or("retained work work hold count")?;*hold=Hold{owner,length,bytes,active:true};self.held+=bytes;Ok(true)}
 pub fn vec_push<T>(&mut self,values:&mut Vec<T>,value:T)->Result<(),(&'static str,T)>{let owner=values as*const Vec<T>as usize;let Some(hold)=self.holds.iter_mut().find(|hold|hold.active&&hold.owner==owner&&hold.length==values.len())else{return Err(("retained work contiguous copy authority missing",value));};if values.len()==values.capacity(){return Err(("retained work contiguous slot missing",value));}self.actual_work+=1;values.push(value);hold.active=false;self.held-=hold.bytes;self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=hold.bytes;Ok(())}
 pub fn push<T>(&mut self,values:&mut PagedList<T,{usize::MAX}>,value:T)->Result<(),(&'static str,T)>{let owner=values as*const PagedList<T,{usize::MAX}>as usize;let Some(hold)=self.holds.iter_mut().find(|hold|hold.active&&hold.owner==owner&&hold.length==values.len())else{return Err(("retained work copy authority missing",value));};let bytes=hold.bytes;match values.push_reserved(value){Ok(())=>{self.actual_work+=1;hold.active=false;self.held-=bytes;self.actual.copied_items=self.actual.copied_items.max(1);self.actual.copied_bytes+=bytes;Ok(())},Err(value)=>Err(("retained work original reservation lost",value))}}
}
